const roh = $input.first().json ?? {};
// Webhook (body) und Formular (body/query) zusammenfuehren
const b = Object.assign({}, roh, typeof roh.body === 'object' && roh.body ? roh.body : {});
const hol = (k, std) => (b[k] === undefined || b[k] === null ? (std ?? '') : String(b[k])).trim();

const arten = ['ansage', 'zeit', 'wetter', 'nachrichten', 'gruss', 'wunsch'];
const art = hol('art', 'ansage').toLowerCase();
const modus = hol('modus', 'live').toLowerCase();

return [{ json: {
  art: arten.includes(art) ? art : 'ansage',
  inhalt: hol('inhalt', ''),
  stimme: hol('stimme', 'de_thorsten'),
  modus: modus === 'einreihen' ? 'einreihen' : 'live',
  quelle: roh.body ? 'webhook/formular' : 'manuell',
} }];

const felder = $('Felder').first().json;
const jetzt = $('Jetzt läuft').first().json;

const zeit = new Date().toLocaleString('de-DE', {
  timeZone: 'Europe/Berlin', hour: '2-digit', minute: '2-digit', weekday: 'long',
  day: '2-digit', month: 'long',
});

const song = (o) => {
  if (!o || !o.song) return null;
  const t = (o.song.text || '').trim();
  return t || null;
};
const gerade = song(jetzt.now_playing);
const danach = song(jetzt.playing_next);
const hoerer = jetzt.listeners ? jetzt.listeners.current : null;

const fakten = [];
fakten.push(`- Aktuelle Uhrzeit: ${zeit} Uhr`);
if (gerade) fakten.push(`- Gerade laeuft: ${gerade}`);
if (danach) fakten.push(`- Als Naechstes: ${danach}`);
if (hoerer !== null) fakten.push(`- Zuhoerer gerade: ${hoerer}`);
let aufgabe = 'Moderiere den Sender und leite zum naechsten Titel ueber.';
let wunschTitel = '';

if (felder.art === 'zeit') {
  aufgabe = 'Sage die aktuelle Uhrzeit und das Datum an, kurz und locker.';
} else if (felder.art === 'wetter') {
  aufgabe = 'Sage das Wetter fuer Marbach am Neckar an: aktuelle Temperatur und die Aussichten.';
  try {
    const r = await fetch('https://api.open-meteo.com/v1/forecast?latitude=48.9347&longitude=9.2586'
      + '&current=temperature_2m,weather_code,wind_speed_10m'
      + '&daily=temperature_2m_max,temperature_2m_min,precipitation_probability_max'
      + '&timezone=Europe%2FBerlin&forecast_days=1');
    const w = await r.json();
    const namen = {0:'klar',1:'ueberwiegend klar',2:'leicht bewoelkt',3:'bewoelkt',45:'neblig',48:'neblig',
      51:'leichter Nieselregen',53:'Nieselregen',55:'starker Nieselregen',61:'leichter Regen',63:'Regen',
      65:'starker Regen',71:'leichter Schneefall',73:'Schneefall',75:'starker Schneefall',
      80:'Regenschauer',81:'Regenschauer',82:'heftige Regenschauer',95:'Gewitter',96:'Gewitter mit Hagel',
      99:'Gewitter mit starkem Hagel'};
    const code = w.current.weather_code;
    fakten.push(`- Wetter jetzt: ${Math.round(w.current.temperature_2m)} Grad, ${namen[code] || 'wechselhaft'}, Wind ${Math.round(w.current.wind_speed_10m)} km/h`);
    fakten.push(`- Heute: ${Math.round(w.daily.temperature_2m_min[0])} bis ${Math.round(w.daily.temperature_2m_max[0])} Grad, Niederschlagswahrscheinlichkeit ${w.daily.precipitation_probability_max[0]} Prozent`);
  } catch (e) {
    fakten.push('- Wetterdaten konnten nicht geladen werden.');
  }
} else if (felder.art === 'nachrichten') {
  aufgabe = 'Fasse die wichtigsten Nachrichten des Tages in zwei bis drei Saetzen zusammen.';
  try {
    const r = await fetch('https://www.tagesschau.de/xml/rss2/');
    const xml = await r.text();
    const titel = [...xml.matchAll(/<item>[\s\S]*?<title>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/title>/g)]
      .map((m) => m[1].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim())
      .filter((t) => t && !t.toLowerCase().includes('tagesschau'))
      .slice(0, 5);
    if (titel.length) {
      fakten.push('- Schlagzeilen heute: ' + titel.join(' | '));
    } else {
      fakten.push('- Keine Schlagzeilen gefunden.');
    }
  } catch (e) {
    fakten.push('- Nachrichten konnten nicht geladen werden.');
  }
} else if (felder.art === 'wunsch') {
  aufgabe = 'Kuendige den Musikwunsch an und gruesse die Person.';
  if (!felder.inhalt) {
    fakten.push('- Es wurde kein Wunschtitel angegeben.');
  } else {
    try {
      const r = await fetch('http://192.168.178.33/api/station/1/files?rowCount=20&searchPhrase='
        + encodeURIComponent(felder.inhalt), { headers: { 'X-API-Key': "DEIN-AZURACAST-SCHLUESSEL" } });
      const treffer = await r.json();
      const liste = Array.isArray(treffer) ? treffer : (treffer.rows || treffer.data || []);
      if (liste.length) {
        const t = liste[0];
        wunschTitel = (t.artist ? t.artist + ' - ' : '') + (t.title || '');
        fakten.push(`- Gewuenschter Titel (aus der Bibliothek): ${wunschTitel}`);
        fakten.push(`- Wunschtext der Hoererin/des Hoerers: ${felder.inhalt}`);
      } else {
        fakten.push(`- Der Wunsch "${felder.inhalt}" ist in der Bibliothek nicht zu finden.`);
      }
    } catch (e) {
      fakten.push('- Die Bibliothek konnte nicht durchsucht werden.');
    }
  }
} else if (felder.art === 'gruss') {
  aufgabe = 'Uebermittle die folgenden Gruesse und Wuensche.';
  if (felder.inhalt) fakten.push(`- Gruesse/Wuensche: ${felder.inhalt}`);
} else {
  if (felder.inhalt) fakten.push(`- Stichwort des Moderators: ${felder.inhalt}`);
}

const prompt = [
  'Du bist Radiomoderator beim Sender "Deadline Beats" und sprichst live ins Mikrofon.',
  'Schreibe eine Ansage auf Deutsch: 2 bis 3 Saetze, hoechstens 45 Woerter.',
  '',
  'Aufgabe: ' + aufgabe,
  '',
  'Belegte Fakten - nenne nur diese, erfinde nichts dazu:',
  fakten.join('\n'),
  '',
  'Regeln:',
  '- Keine Begruessung wie "Guten Morgen" oder "Guten Abend", wenn sie nicht zu den Fakten passt.',
  '- Keine Aufzaehlungen, keine Emojis, keine Anfuehrungszeichen, keine Regieanweisungen.',
  '- Nenne Uhrzeit und Titel genau so, wie sie oben stehen.',
  '- Gesprochene Sprache, kein Schriftdeutsch.',
  'Antworte ausschliesslich mit dem Ansagetext.',
].join('\n');

return [{ json: { prompt, art: felder.art, stimme: felder.stimme, modus: felder.modus,
                  wunsch_titel: wunschTitel, song_aktuell: gerade, song_naechster: danach } }];

const text = ($json.response || '').toString().trim();
let sauber = text
  .replace(/^```[\s\S]*?\n/, '')
  .replace(/```/g, '')
  .replace(/^\s*(Ansage|Moderation|Text)\s*:\s*/i, '')
  .replace(/[*_#`>]/g, '')
  .replace(/["\u201c\u201d]/g, '')
  .replace(/\s+/g, ' ')
  .trim();
if (sauber && !/[.!?]$/.test(sauber)) sauber += '.';
return [{ json: { text: sauber, art: $('Recherche').first().json.art,
                  stimme: $('Recherche').first().json.stimme,
                  modus: $('Recherche').first().json.modus,
                  wunsch_titel: $('Recherche').first().json.wunsch_titel } }];

const j = $input.first().json;
const bin = $input.first().binary;
const name = 'ansage_' + Date.now() + '.mp3';
if (bin && bin.data) { bin.data.fileName = name; bin.data.mimeType = 'audio/mpeg'; }
return [{ json: Object.assign({}, j, { dateiname: name }), binary: bin }];

// Ersten Suchtreffer herausnehmen - Zuordnen und Wunsch abgeben brauchen ihn.
const roh = $input.first().json || {};
if (roh.error) return [{ json: { fehler: 'Der Sender antwortet gerade nicht.' } }];
const zeilen = roh.rows || roh.data || (Array.isArray(roh) ? roh : []);
if (!zeilen.length) return [{ json: { fehler: 'Kein Titel zum Ansagen gefunden.' } }];
return [{ json: zeilen[0] }];
